from typing import List, Tuple
from collections import Counter

def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise
    """
    total_area = h * w
    # Normalize tiles so (a, b) where a <= b
    normalized_tiles = [tuple(sorted(t)) for t in tiles]
    if sum(a * b for a, b in normalized_tiles) < total_area:
        return False

    grid = [[False for _ in range(w)] for _ in range(h)]
    tile_counts = Counter(normalized_tiles)
    unique_tiles = sorted(tile_counts.keys(), key=lambda x: x[0] * x[1], reverse=True)

    def solve(remaining_area, current_available_area):
        if remaining_area == 0:
            return True

        if current_available_area < remaining_area:
            return False

        # Find first empty cell
        r, c = -1, -1
        for i in range(h):
            for j in range(w):
                if not grid[i][j]:
                    r, c = i, j
                    break
            if r != -1: break

        if r == -1: # This case is handled by remaining_area == 0 but for safety
            return remaining_area == 0

        for tile in unique_tiles:
            if tile_counts[tile] > 0:
                th_orig, tw_orig = tile
                # Try rotations
                for th, tw in set([(th_orig, tw_orig), (tw_orig, th_orig)]):
                    if r + th <= h and c + tw <= w:
                        # Check if all cells in the tile are free
                        can_place = True
                        for rh in range(r, r + th):
                            for cw in range(c, c + tw):
                                if grid[rh][cw]:
                                    can_place = False
                                    break
                            if not can_place: break

                        if can_place:
                            # Place tile
                            for rh in range(r, r + th):
                                for cw in range(c, c + tw):
                                    grid[rh][cw] = True

                            tile_counts[tile] -= 1
                            if solve(remaining_area - th * tw, current_available_area - th * tw):
                                return True
                            tile_counts[tile] += 1

                            # Backtrack
                            for rh in range(r, r + th):
                                for cw in range(c, c + tw):
                                    grid[rh][cw] = False
        return False

    initial_available_area = sum(a * b for a, b in normalized_tiles)
    return solve(total_area, initial_available_area)

def sum_of_scores(n: int, m: int) -> int:
    MOD = 998244353

    if m == 0:
        return 0

    primes = [2, 3, 5, 7, 11, 13]
    relevant_primes = [p for p in primes if p <= m]
    num_primes = len(relevant_primes)
    num_states = 1 << num_primes

    def get_vp(x, p):
        count = 0
        while x > 0 and x % p == 0:
            count += 1
            x //= p
        return count

    c = [0] * num_states
    for x in range(1, m + 1):
        # For each x, we can contribute to all c(T)
        # c(T) = sum_{x=1}^m product_{p in T} v_p(x)
        vps = [get_vp(x, p) for p in relevant_primes]
        for mask in range(num_states):
            prod = 1
            for i in range(num_primes):
                if (mask >> i) & 1:
                    prod *= vps[i]
            c[mask] = (c[mask] + prod) % MOD

    # Matrix M: M[S][S'] = c(S ^ S') if (S & S') == S' else 0
    # Actually, the recurrence is:
    # V_{k+1}[S] = sum_{S' subset S} c(S \ S') V_k[S']
    # Let's use the binary exponentiation for sum of matrices
    # sum_{k=1}^n M^k = (M + M^2 + ... + M^n)

    def mat_mul(A, B):
        C = [[0] * num_states for _ in range(num_states)]
        for i in range(num_states):
            row_A = A[i]
            for k in range(num_states):
                val_A = row_A[k]
                if val_A == 0:
                    continue
                row_B = B[k]
                for j in range(num_states):
                    C[i][j] = (C[i][j] + val_A * row_B[j]) % MOD
        return C

    def mat_vec_mul(A, v):
        res = [0] * num_states
        for i in range(num_states):
            row_A = A[i]
            tmp = 0
            for j in range(num_states):
                tmp = (tmp + row_A[j] * v[j]) % MOD
            res[i] = tmp
        return res

    # We want S(n) = sum_{k=1}^n M^k.
    # S(1) = M
    # S(2n) = S(n) + M^n * S(n) = (I + M^n) S(n)
    # S(2n+1) = S(2n) + M^{2n+1}

    M = [[0] * num_states for _ in range(num_states)]
    for s in range(num_states):
        for s_prime in range(num_states):
            if (s & s_prime) == s_prime:
                M[s][s_prime] = c[s ^ s_prime]

    def solve_sum(n):
        if n == 0:
            return [[0] * num_states for _ in range(num_states)], [[0] * num_states for _ in range(num_states)]
        if n == 1:
            return M, M # return (M^1, S(1))

        if n % 2 == 0:
            Mn, Sn = solve_sum(n // 2)
            # M^{2n} = M^n * M^n
            # S(2n) = (I + M^n) * S(n)
            M2n = mat_mul(Mn, Mn)

            # I + Mn
            I_plus_Mn = [row[:] for row in Mn]
            for i in range(num_states):
                I_plus_Mn[i][i] = (I_plus_Mn[i][i] + 1) % MOD

            S2n = mat_mul(I_plus_Mn, Sn)
            return M2n, S2n
        else:
            Mn, Sn = solve_sum(n - 1)
            # M^{n} = M * M^{n-1}
            # S(n) = S(n-1) + M^n
            Mn_plus_1 = mat_mul(M, Mn)
            S_plus_1 = [row[:] for row in Sn]
            for i in range(num_states):
                for j in range(num_states):
                    S_plus_1[i][j] = (S_plus_1[i][j] + Mn_plus_1[i][j]) % MOD
            return Mn_plus_1, S_plus_1

    _, Sn = solve_sum(n)

    # Final answer: sum_{S} (S(n) * V_0)[S]
    # V_0 = [1, 0, ..., 0]
    # (S(n) * V_0)[S] = Sn[S][0]
    ans = sum(Sn[s][0] for s in range(num_states)) % MOD
    return ans

