def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    n = len(s)

    # Precompute costs for all substrings
    # cost[i][j] is the cost to make s[i:j] a semi-palindrome
    # Using a 2D array for better performance
    cost = [[float('inf')] * (n + 1) for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length
            t = s[i:j]

            min_val = float('inf')
            # Find divisors d of length such that 1 <= d < length
            for d in range(1, length):
                if length % d == 0:
                    current_cost = 0
                    m = length // d
                    # For each remainder r, we have a sequence of length m
                    # The sequence is t[r], t[r+d], ..., t[r+(m-1)d]
                    for r in range(d):
                        # Palindrome cost for the sequence
                        for idx in range(m // 2):
                            if t[r + idx * d] != t[r + (m - 1 - idx) * d]:
                                current_cost += 1
                    if current_cost < min_val:
                        min_val = current_cost
            cost[i][j] = min_val

    # DP: dp[j][i] is the min cost to partition s[0:i] into j substrings
    # Each substring must have length >= 2
    dp = [[float('inf')] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0

    for j in range(1, k + 1):
        # We need at least 2*j characters for j substrings of length >= 2
        for i in range(2 * j, n + 1):
            # The last substring is s[p:i], length is i-p >= 2 => p <= i-2
            # Also we need at least 2*(j-1) characters for the first j-1 substrings => p >= 2*(j-1)
            for p in range(2 * (j - 1), i - 1):
                if dp[j - 1][p] != float('inf') and cost[p][i] != float('inf'):
                    new_val = dp[j - 1][p] + cost[p][i]
                    if new_val < dp[j][i]:
                        dp[j][i] = new_val

    return int(dp[k][n])

